import 'package:flutter/material.dart';import '../widgets/ui.dart';import '../data/sai_repository.dart';import 'roster.dart';
class ClassesScreen extends StatelessWidget{const ClassesScreen({super.key,required this.repo});final SaiRepository repo;@override Widget build(BuildContext context)=>SaiPage(title:'الصفوف',subtitle:'الصفوف المتاحة لحسابك',children:[AsyncList(future:repo.classes(),builder:(rows)=>Column(children:[for(final r in rows)SaiTile(title:r['name']?.toString()??'صف',subtitle:'${r['program']??''} · السعة ${r['capacity']??'—'}',icon:Icons.class_outlined,onTap:()=>Navigator.push(context,MaterialPageRoute(builder:(_)=>RosterScreen(repo:repo,classRow:r)))])))]);}
